<script setup lang="ts">
import { formatPh } from '@/utils/philippineTime';
import { computed, ref } from 'vue';
import { Link } from '@inertiajs/vue3';
import DataTable from '@/Components/UI/DataTable.vue';
import StatusBadge from '@/Components/UI/StatusBadge.vue';
import ContentState from '@/Components/UI/ContentState.vue';
import type { CaseActionRow } from '@/types/casework';
const props=defineProps<{rows:CaseActionRow[];asOf?:string;compact?:boolean}>();
const expanded=ref(false);
const visibleRows=computed(()=>expanded.value?props.rows:props.rows.slice(0,5));
const columns=[{key:'case',label:'Case / stage'},{key:'action',label:'Next recorded action'},{key:'priority',label:'Priority'},{key:'due',label:'Due date'}];
const priorityTone=(value:string)=>value==='urgent'||value==='high'?'danger':value==='low'?'success':'warning';
const label=(value:string)=>value.replaceAll('_',' ').toLowerCase().replace(/^\w/,letter=>letter.toUpperCase());
const overdue=(value:string|null)=>Boolean(value && Date.parse(value)<(props.asOf?Date.parse(props.asOf):Date.now()));
const date=(value:string|null)=>formatPh(value,'dateTimeShort','No due date');
</script>
<template><section class="ui-panel overflow-hidden" aria-labelledby="case-action-queue-title"><header class="ui-panel-header"><div><div class="flex flex-wrap items-center gap-2"><h2 id="case-action-queue-title" class="ui-section-title">My cases requiring action</h2><span v-if="rows.filter(row=>overdue(row.due_at)).length" class="ui-pill bg-rose-600 text-white">{{rows.filter(row=>overdue(row.due_at)).length}} overdue</span></div><p class="mt-1 max-w-xl text-xs leading-5 text-slate-600">Your open case tasks, earliest due first.</p></div><Link :href="route('calendar.index')" class="ui-link">Open calendar</Link></header><DataTable v-if="rows.length" :stacked="compact" :rows="visibleRows" :columns="columns" :row-key="row=>row.task_id" label="Case action queue"><template #row="{row}"><td class="max-w-[12rem] px-4 py-1"><Link :href="route('cases.show',row.case_id)" class="flex min-h-11 flex-col justify-center break-words text-xs font-semibold text-brand-800 hover:underline"><span>{{row.case_number}}</span><span class="mt-1 text-[11px] font-normal text-slate-600">{{label(row.stage)}}<template v-if="row.stage!==row.status"> / {{label(row.status)}}</template></span></Link></td><td class="max-w-[17rem] break-words px-4 py-2 leading-6 text-slate-800">{{row.next_action}}</td><td class="px-4 py-2"><StatusBadge :label="label(row.priority)" :tone="priorityTone(row.priority)" /></td><td class="px-4 py-2"><p class="text-xs leading-5" :class="overdue(row.due_at)?'font-semibold text-rose-800':'text-slate-700'">{{date(row.due_at)}}</p><p v-if="overdue(row.due_at)" class="mt-1 text-xs font-semibold text-rose-800">Overdue</p></td></template><template #card="{row}"><div class="flex flex-wrap items-center justify-between gap-2"><Link :href="route('cases.show',row.case_id)" class="ui-link">{{row.case_number}}</Link><StatusBadge :label="label(row.priority)" :tone="priorityTone(row.priority)" /></div><p class="mt-1 break-words text-sm font-medium text-slate-900">{{row.next_action}}</p><p class="mt-2 text-xs text-slate-600">{{label(row.stage)}}<template v-if="row.stage!==row.status"> / {{label(row.status)}}</template></p><p class="mt-2 text-xs" :class="overdue(row.due_at)?'font-semibold text-rose-800':'text-slate-700'">{{date(row.due_at)}}<span v-if="overdue(row.due_at)"> - Overdue</span></p></template></DataTable><div v-if="rows.length > 5" class="border-t border-slate-200 px-4 py-2"><button type="button" class="ui-link" :aria-expanded="expanded" @click="expanded=!expanded">{{expanded?'Show first 5 tasks':`Show all ${rows.length} queued tasks`}}</button></div><div v-if="!rows.length" class="p-4"><ContentState title="No open case tasks recorded" description="Check follow-up cases and your calendar for other work." /></div></section></template>
